finalizationCommands:
$ErrorActionPreference = 'Stop'
Set-Location -LiteralPath 'L:/zero-server'
$evidence = 'target/performance-third-20260923'
while (!(Test-Path -LiteralPath "$evidence/soak-two-hours/completed.json")) {
    if (!(Get-Process -Id 28308 -ErrorAction SilentlyContinue) -and !(Test-Path -LiteralPath "$evidence/soak-two-hours/completed.json")) { throw 'Load matrix exited without soak completion' }
    Start-Sleep -Seconds 10
}
& 'scripts/performance/RunThirdRoundGcControlled.ps1' -Evidence $evidence -IncludeChain *> "$evidence/controlled-confirm.log"
if (!$?) { throw 'Controlled load confirmation failed' }
& 'scripts/performance/RunThirdRoundWarmBurst.ps1' -Evidence $evidence *> "$evidence/warm-burst.log"
if (!$?) { throw 'Warm TLS burst confirmation failed' }
$env:JAVA_HOME = 'D:/env/jdk21'
$env:PATH = 'D:/env/jdk21/bin;' + $env:PATH
& mvn '-Pquality,benchmarks' -pl zero-benchmarks -am verify -DskipITs *> "$evidence/load-driver-quality.log"
if ($LASTEXITCODE -ne 0) { throw 'Final load-driver quality verification failed' }
Copy-Item -LiteralPath 'zero-benchmarks/target/benchmarks.jar' -Destination "$evidence/delivery.jar"
& 'D:/env/jdk21/bin/java.exe' scripts/ZeroArchitectureGuard.java *> "$evidence/architecture-final.log"
if ($LASTEXITCODE -ne 0) { throw 'Architecture guard failed' }
& 'D:/env/jdk21/bin/java.exe' scripts/VerifyPublicApiCompatibility.java --check *> "$evidence/api-final.log"
if ($LASTEXITCODE -ne 0) { throw 'Public API guard failed' }
& python scripts/performance/AnalyzeThirdRoundJfr.py *> "$evidence/jfr-analysis.log"
if ($LASTEXITCODE -ne 0) { throw 'JFR analysis failed' }
& python scripts/performance/SummarizeThirdRoundLoad.py *> "$evidence/load-summary-table.md"
if ($LASTEXITCODE -ne 0) { throw 'Load summary failed' }
& python scripts/performance/CollectThirdRoundEvidence.py *> "$evidence/evidence-collection.log"
if ($LASTEXITCODE -ne 0) { throw 'Evidence collection failed' }
@{ finishedAt = (Get-Date -Format o) } | ConvertTo-Json | Set-Content -Encoding utf8 "$evidence/finalization-completed.json"
